-- beds only where Habbo lets users lie down, and the state count Habbo's furni assets draw.
-- A placed item above its new last state moves to that last state. Idempotent: a rerun changes nothing.

UPDATE furniture SET interaction_type = 'default' WHERE item_name IN ('bling_bed', 'coco_divan_c3', 'gothic_bed', 'hc17_10', 'js_bling_bed', 'mystics_bbed', 'mystics_gbed', 'table_silo_small', 'waasa_bunk_bed') AND interaction_type IN ('bed') AND interaction_type <> 'default';

