UPDATE furniture SET can_stack = 0 WHERE item_name IN ('anc_pharaoh_tele', 'cine_curtain_red', 'hween14_lovelock', 'plant_rose_black', 'scifiport*0', 'val15_tele') AND can_stack <> 0;

